                        <div className="flex gap-2 mt-2">
                           <span className={`px-2 py-1 rounded text-xs font-bold ${viewingItem.condition === 'New' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                              {viewingItem.condition}
                           </span>
