                     </select>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Price</label>
                        <input type="number" required className="w-full px-3 py-2 border rounded-lg" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} />
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Quantity</label>
                        <input type="number" required className="w-full px-3 py-2 border rounded-lg" value={formData.quantity} onChange={e => setFormData({...formData, quantity: e.target.value})} />
