                     <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-lg font-bold">Save</button>
                  </div>
               </form>
            </div>
         </div>
      )}

      {/* Sell Modal */}
      {isSellModalOpen && sellingItem && (
