      case 'sales-history':
        const sortedVouchers = vouchers.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full animate-fade-in">
