                   <tbody className="divide-y divide-slate-100">
                      {sortedVouchers.map(v => (
                         <tr key={v.id} className={`hover:bg-slate-50 cursor-pointer ${v.status === 'Refunded' ? 'bg-red-50/50 hover:bg-red-50' : ''}`} onClick={() => setSelectedVoucher(v)}>
