  PlusCircle, 
  Save, 
  LogOut, 
  Search, 
  Headphones, 
  DollarSign, 
  TrendingUp, 
  Download, 
  Upload, 
  Filter, 
  Edit, 
  Trash2, 
  Minus, 
  Plus, 
  Calendar as CalendarIcon,
  ShoppingBag,
  Printer,
  Settings,
  X,
  Check,
  Barcode,
  MapPin,
  Phone,
  FileText,
  User,
  ShieldAlert,
  Lock,
  RotateCcw,
  Database,
  Percent
} from 'lucide-react';
