        const weekAgo = new Date(now);
        weekAgo.setDate(now.getDate() - 7);
        return targetDate >= weekAgo && targetDate <= now;
      }

      if (salesDateFilter === 'month') {
        return targetDate.getMonth() === now.getMonth() && targetDate.getFullYear() === now.getFullYear();
