                       className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                     >
                       <option value="">Select Error Type</option>
                       {repairErrors.map((error, idx) => (
