              </div>

              <div className="flex-1 overflow-auto">
                 <table className="w-full text-left">
                   <thead className="bg-slate-50 sticky top-0 z-10">
                     <tr className="text-[10px] font-bold text-slate-500 uppercase">
                       {listTab === 'completed' ? (
                         <>
