import React, { useState, useRef, useEffect } from 'react';
import { 
  ShoppingBag, 
  Package, 
  History, 
  Save, 
  LogOut, 
  Search, 
  Plus, 
  Minus, 
  Trash2, 
  ShoppingCart, 
  Printer,
  Tags,
  PlusCircle,
  Edit,
  ShieldAlert
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup } from '../services/storage';

interface AccessoriesSalesDashboardProps {
  onLogout: () => void;
}

// Interfaces
interface AccessoryItem {
  id: string;
  name: string;
  category: string;
  price: number;
  stock: number;
  code?: string;
}

interface CartItem extends AccessoryItem {
  quantity: number;
}

interface SaleRecord {
  id: string;
  date: string;
  items: CartItem[];
  totalAmount: number;
  paymentMethod: 'Cash' | 'KPay' | 'WavePay';
  customerName?: string;
}

interface Category {
  id: string;
  name: string;
}

// Default Data
const DEFAULT_CATEGORIES: Category[] = [
  { id: 'cat1', name: 'Case' },
  { id: 'cat2', name: 'Screen Guard' },
  { id: 'cat3', name: 'Charger' },
  { id: 'cat4', name: 'Cable' },
  { id: 'cat5', name: 'Audio' },
  { id: 'cat6', name: 'Power Bank' },
];

const DEFAULT_INVENTORY: AccessoryItem[] = [
  { id: 'acc1', name: 'iPhone 13 Case Clear', category: 'Case', price: 5000, stock: 10, code: 'C001' },
  { id: 'acc2', name: 'Fast Charger 20W', category: 'Charger', price: 15000, stock: 5, code: 'CH001' },
];

export const AccessoriesSalesDashboard: React.FC<AccessoriesSalesDashboardProps> = ({ onLogout }) => {
  // State
  const [currentView, setCurrentView] = useState<'pos' | 'inventory' | 'sales' | 'backup'>('pos');
  const [inventory, setInventory] = useState<AccessoryItem[]>(() => loadData(StorageKeys.ACCESSORIES_INVENTORY, DEFAULT_INVENTORY));
  const [sales, setSales] = useState<SaleRecord[]>(() => loadData(StorageKeys.ACCESSORIES_SALES, []));
  const [categories, setCategories] = useState<Category[]>(() => loadData(StorageKeys.ACCESSORIES_CATEGORIES, DEFAULT_CATEGORIES));

  // Cart State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  // Modal States
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [checkoutData, setCheckoutData] = useState({ paymentMethod: 'Cash', customerName: '' });
  const [lastSale, setLastSale] = useState<SaleRecord | null>(null);

  const [isInventoryModalOpen, setIsInventoryModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<AccessoryItem | null>(null);
  const [itemFormData, setItemFormData] = useState({ name: '', category: '', price: '', stock: '', code: '' });

  const [isSecurityModalOpen, setIsSecurityModalOpen] = useState(false);
  const [securityPassword, setSecurityPassword] = useState('');
  const [securityAction, setSecurityAction] = useState<'delete_sale' | 'delete_item' | null>(null);
  const [securityTargetId, setSecurityTargetId] = useState<string | null>(null);
  const [securityError, setSecurityError] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => saveData(StorageKeys.ACCESSORIES_INVENTORY, inventory), [inventory]);
  useEffect(() => saveData(StorageKeys.ACCESSORIES_SALES, sales), [sales]);
  useEffect(() => saveData(StorageKeys.ACCESSORIES_CATEGORIES, categories), [categories]);

  // POS Logic
  const addToCart = (item: AccessoryItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        if (existing.quantity >= item.stock) return prev; // Stock limit
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => prev.filter(i => i.id !== itemId));
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        const newQty = i.quantity + delta;
        const itemInStock = inventory.find(inv => inv.id === itemId);
        if (newQty < 1) return i;
        if (itemInStock && newQty > itemInStock.stock) return i;
        return { ...i, quantity: newQty };
      }
      return i;
    }));
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleCheckout = () => {
    if (cart.length === 0) return;
    setIsCheckoutOpen(true);
  };

  const confirmCheckout = () => {
    const newSale: SaleRecord = {
      id: `INV-${Date.now()}`,
      date: new Date().toISOString(),
      items: [...cart],
      totalAmount: cartTotal,
      paymentMethod: checkoutData.paymentMethod as any,
      customerName: checkoutData.customerName
    };

    // Update Stock
    setInventory(prev => prev.map(item => {
      const cartItem = cart.find(c => c.id === item.id);
      if (cartItem) {
        return { ...item, stock: item.stock - cartItem.quantity };
      }
      return item;
    }));

    setSales(prev => [newSale, ...prev]);
    setCart([]);
    setIsCheckoutOpen(false);
    setCheckoutData({ paymentMethod: 'Cash', customerName: '' });
    setLastSale(newSale); // Trigger receipt modal
  };

  // Inventory Logic
  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    const newItem: AccessoryItem = {
      id: editingItem ? editingItem.id : `acc-${Date.now()}`,
      name: itemFormData.name,
      category: itemFormData.category,
      price: Number(itemFormData.price),
      stock: Number(itemFormData.stock),
      code: itemFormData.code
    };

    if (editingItem) {
      setInventory(prev => prev.map(i => i.id === editingItem.id ? newItem : i));
    } else {
      setInventory(prev => [newItem, ...prev]);
    }
    setIsInventoryModalOpen(false);
    setEditingItem(null);
    setItemFormData({ name: '', category: '', price: '', stock: '', code: '' });
  };

  const openInventoryModal = (item?: AccessoryItem) => {
    if (item) {
      setEditingItem(item);
      setItemFormData({
        name: item.name,
        category: item.category,
        price: String(item.price),
        stock: String(item.stock),
        code: item.code || ''
      });
    } else {
      setEditingItem(null);
      setItemFormData({ name: '', category: categories[0]?.name || '', price: '', stock: '', code: '' });
    }
    setIsInventoryModalOpen(true);
  };

  // Security Logic
  const initiateSecurityAction = (action: 'delete_sale' | 'delete_item', id: string) => {
    setSecurityAction(action);
    setSecurityTargetId(id);
    setSecurityPassword('');
    setSecurityError('');
    setIsSecurityModalOpen(true);
  };

  const handleSecuritySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (securityPassword === '1471656') {
      if (securityAction === 'delete_sale' && securityTargetId) {
        setSales(prev => prev.filter(s => s.id !== securityTargetId));
      } else if (securityAction === 'delete_item' && securityTargetId) {
        setInventory(prev => prev.filter(i => i.id !== securityTargetId));
      }
      setIsSecurityModalOpen(false);
    } else {
      setSecurityError('Incorrect Password');
    }
  };

  // Backup
  const handleBackup = () => createFullBackup('HHS_ACCESSORIES');

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
     const file = e.target.files?.[0];
     if (!file) return;
     const reader = new FileReader();
     reader.onload = (event) => {
        try {
           const data = JSON.parse(event.target?.result as string);
           if (data.accessoriesInventory) setInventory(data.accessoriesInventory);
           if (data.accessoriesSales) setSales(data.accessoriesSales);
           alert('Data Restored');
        } catch(e) { alert('Error restoring data'); }
     };
     reader.readAsText(file);
  };

  // Receipt Printing
  const printReceipt = () => {
     const element = document.getElementById('receipt-content');
     if (element) {
        const opt = {
           margin: 0,
           filename: `Receipt-${lastSale?.id}.pdf`,
           image: { type: 'jpeg', quality: 0.98 },
           html2canvas: { scale: 2 },
           jsPDF: { unit: 'mm', format: [80, 200] } // Thermal printer width approx
        };
        // @ts-ignore
        html2pdf().set(opt).from(element).save();
     }
  };

  const filteredInventory = inventory.filter(i => {
    const matchesSearch = i.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          (i.code && i.code.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesCategory = selectedCategory === 'All' || i.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col z-20 shadow-xl">
        <div className="p-6 border-b border-slate-100">
          <h2 className="font-display font-bold text-xl text-slate-900">{BRAND_NAME}</h2>
          <p className="text-xs font-bold text-teal-600 uppercase tracking-widest mt-1">Accessories</p>
        </div>
        <nav className="flex-1 p-4 space-y-2">
           <button onClick={() => setCurrentView('pos')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'pos' ? 'bg-teal-50 text-teal-600 font-bold' : 'text-slate-500 hover:bg-slate-50'}`}>
              <ShoppingBag className="w-5 h-5" /> POS
           </button>
           <button onClick={() => setCurrentView('inventory')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'inventory' ? 'bg-teal-50 text-teal-600 font-bold' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Package className="w-5 h-5" /> Inventory
           </button>
           <button onClick={() => setCurrentView('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'sales' ? 'bg-teal-50 text-teal-600 font-bold' : 'text-slate-500 hover:bg-slate-50'}`}>
              <History className="w-5 h-5" /> Sales History
           </button>
           <button onClick={() => setCurrentView('backup')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'backup' ? 'bg-teal-50 text-teal-600 font-bold' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Save className="w-5 h-5" /> Backup
           </button>
        </nav>
        <div className="p-4 border-t border-slate-100">
          <button onClick={() => { handleBackup(); setTimeout(onLogout, 500); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-50 font-medium">
             <LogOut className="w-5 h-5" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
         <header className="h-16 bg-white/80 backdrop-blur-md border-b border-slate-200 flex items-center justify-between px-8 z-10 sticky top-0">
            <h1 className="text-xl font-bold text-slate-800 capitalize">{currentView === 'pos' ? 'Point of Sale' : currentView}</h1>
            <div className="flex items-center gap-4">
              <div className="w-8 h-8 rounded-full bg-teal-100 border border-teal-200 flex items-center justify-center text-teal-700 font-bold text-xs">AD</div>
            </div>
         </header>

         <div className="flex-1 overflow-hidden p-4">
            {currentView === 'pos' && (
               <div className="flex h-full gap-4">
                  {/* Item Grid */}
                  <div className="flex-1 flex flex-col gap-4">
                     <div className="bg-white p-4 rounded-xl border border-slate-100 flex gap-4">
                        <div className="relative flex-1">
                           <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                           <input type="text" placeholder="Search items..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:border-teal-500" />
                        </div>
                        <select value={selectedCategory} onChange={e => setSelectedCategory(e.target.value)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg outline-none">
                           <option value="All">All Categories</option>
                           {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                     </div>
                     <div className="flex-1 overflow-y-auto">
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                           {filteredInventory.map(item => (
                              <button key={item.id} onClick={() => addToCart(item)} disabled={item.stock <= 0} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-all text-left flex flex-col h-full disabled:opacity-50">
                                 <div className="flex justify-between items-start mb-2">
                                    <div className="p-2 bg-teal-50 rounded-lg text-teal-600"><Tags className="w-4 h-4" /></div>
                                    <span className={`text-xs font-bold px-2 py-1 rounded ${item.stock > 0 ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>{item.stock > 0 ? `${item.stock} in stock` : 'Out of Stock'}</span>
                                 </div>
                                 <h4 className="font-bold text-slate-800 mb-1 line-clamp-2">{item.name}</h4>
                                 <p className="text-xs text-slate-500 mb-auto">{item.category}</p>
                                 <p className="text-lg font-bold text-teal-600 mt-2">{item.price.toLocaleString()} K</p>
                              </button>
                           ))}
                        </div>
                     </div>
                  </div>

                  {/* Cart Sidebar */}
                  <div className="w-96 bg-white rounded-2xl shadow-xl border border-slate-100 flex flex-col">
                     <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                        <h3 className="font-bold text-slate-800 flex items-center gap-2"><ShoppingCart className="w-5 h-5" /> Current Sale</h3>
                        <span className="bg-teal-100 text-teal-700 px-2 py-1 rounded text-xs font-bold">{cart.length} Items</span>
                     </div>
                     <div className="flex-1 overflow-y-auto p-4 space-y-3">
                        {cart.map(item => (
                           <div key={item.id} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                              <div className="flex-1">
                                 <h5 className="font-bold text-slate-800 text-sm">{item.name}</h5>
                                 <p className="text-xs text-teal-600 font-bold">{item.price.toLocaleString()} K</p>
                              </div>
                              <div className="flex items-center gap-3">
                                 <div className="flex items-center bg-white rounded-lg border border-slate-200">
                                    <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-slate-100"><Minus className="w-3 h-3" /></button>
                                    <span className="w-8 text-center text-xs font-bold">{item.quantity}</span>
                                    <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-slate-100"><Plus className="w-3 h-3" /></button>
                                 </div>
                                 <button onClick={() => removeFromCart(item.id)} className="text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                              </div>
                           </div>
                        ))}
                        {cart.length === 0 && <div className="text-center text-slate-400 py-10">Cart is empty</div>}
                     </div>
                     <div className="p-4 border-t border-slate-100 bg-slate-50">
                        <div className="flex justify-between items-center mb-4">
                           <span className="text-slate-500 font-bold">Total</span>
                           <span className="text-2xl font-bold text-slate-900">{cartTotal.toLocaleString()} K</span>
                        </div>
                        <button onClick={handleCheckout} disabled={cart.length === 0} className="w-full py-3 bg-teal-600 text-white font-bold rounded-xl shadow-lg shadow-teal-200 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed">
                           Proceed to Checkout
                        </button>
                     </div>
                  </div>
               </div>
            )}

            {currentView === 'inventory' && (
               <div className="bg-white rounded-2xl border border-slate-100 h-full flex flex-col">
                  <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                     <h3 className="font-bold text-slate-800">Inventory Management</h3>
                     <button onClick={() => openInventoryModal()} className="px-4 py-2 bg-teal-600 text-white rounded-lg font-bold text-sm flex items-center gap-2"><PlusCircle className="w-4 h-4" /> Add Item</button>
                  </div>
                  <div className="p-4 flex gap-4 bg-slate-50">
                     <input type="text" placeholder="Search inventory..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg outline-none" />
                  </div>
                  <div className="flex-1 overflow-auto">
                     <table className="w-full text-left">
                        <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                           <tr>
                              <th className="p-4">Item Name</th>
                              <th className="p-4">Category</th>
                              <th className="p-4">Stock</th>
                              <th className="p-4 text-right">Price</th>
                              <th className="p-4 text-right">Actions</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                           {filteredInventory.map(item => (
                              <tr key={item.id} className="hover:bg-slate-50">
                                 <td className="p-4 font-bold text-slate-700">{item.name} <span className="text-xs text-slate-400 font-normal block">{item.code}</span></td>
                                 <td className="p-4 text-sm text-slate-600">{item.category}</td>
                                 <td className="p-4"><span className={`px-2 py-1 rounded text-xs font-bold ${item.stock > 5 ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>{item.stock}</span></td>
                                 <td className="p-4 text-right font-bold text-slate-800">{item.price.toLocaleString()}</td>
                                 <td className="p-4 text-right">
                                    <button onClick={() => openInventoryModal(item)} className="p-2 text-slate-400 hover:text-teal-600"><Edit className="w-4 h-4" /></button>
                                    <button onClick={() => initiateSecurityAction('delete_item', item.id)} className="p-2 text-slate-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                 </td>
                              </tr>
                           ))}
                        </tbody>
                     </table>
                  </div>
               </div>
            )}

            {currentView === 'sales' && (
               <div className="bg-white rounded-2xl border border-slate-100 h-full flex flex-col">
                  <div className="p-4 border-b border-slate-100"><h3 className="font-bold text-slate-800">Sales Transactions</h3></div>
                  <div className="flex-1 overflow-auto">
                     <table className="w-full text-left">
                        <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                           <tr>
                              <th className="p-4">Date</th>
                              <th className="p-4">Transaction ID</th>
                              <th className="p-4">Customer</th>
                              <th className="p-4">Items</th>
                              <th className="p-4 text-right">Total</th>
                              <th className="p-4 text-right">Action</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                           {sales.map(sale => (
                              <tr key={sale.id} className="hover:bg-slate-50">
                                 <td className="p-4 text-sm text-slate-600">{new Date(sale.date).toLocaleString()}</td>
                                 <td className="p-4 font-mono text-xs text-slate-500">{sale.id}</td>
                                 <td className="p-4 font-bold text-slate-700">{sale.customerName || 'Walk-in'}</td>
                                 <td className="p-4 text-sm text-slate-600">{sale.items.length} items</td>
                                 <td className="p-4 text-right font-bold text-teal-600">{sale.totalAmount.toLocaleString()}</td>
                                 <td className="p-4 text-right">
                                    <button onClick={() => { setLastSale(sale); }} className="p-2 text-slate-400 hover:text-teal-600"><Printer className="w-4 h-4" /></button>
                                    <button onClick={() => initiateSecurityAction('delete_sale', sale.id)} className="p-2 text-slate-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                 </td>
                              </tr>
                           ))}
                        </tbody>
                     </table>
                  </div>
               </div>
            )}

            {currentView === 'backup' && (
                <div className="bg-white p-8 rounded-2xl border border-slate-100 max-w-2xl mx-auto mt-10 text-center">
                   <h3 className="text-xl font-bold text-slate-800 mb-6">Backup & Restore</h3>
                   <div className="flex gap-4 justify-center">
                      <button onClick={handleBackup} className="px-6 py-3 bg-teal-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-teal-700"><Download className="w-5 h-5" /> Export Data</button>
                      <div className="relative">
                         <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
                         <button onClick={() => fileInputRef.current?.click()} className="px-6 py-3 bg-slate-800 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-slate-700"><Upload className="w-5 h-5" /> Import Data</button>
                      </div>
                   </div>
                </div>
            )}
         </div>
      </main>

      {/* Checkout Modal */}
      {isCheckoutOpen && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
               <h3 className="text-xl font-bold text-slate-800 mb-4">Complete Sale</h3>
               <div className="space-y-4">
                  <div>
                     <label className="text-xs font-bold text-slate-500 uppercase">Total Amount</label>
                     <p className="text-3xl font-bold text-teal-600">{cartTotal.toLocaleString()} K</p>
                  </div>
                  <div>
                     <label className="text-xs font-bold text-slate-500 uppercase">Payment Method</label>
                     <div className="flex gap-2 mt-1">
                        {['Cash', 'KPay', 'WavePay'].map(m => (
                           <button key={m} onClick={() => setCheckoutData({...checkoutData, paymentMethod: m as any})} className={`flex-1 py-2 rounded-lg font-bold text-sm border ${checkoutData.paymentMethod === m ? 'bg-teal-50 border-teal-500 text-teal-700' : 'border-slate-200 text-slate-600'}`}>{m}</button>
                        ))}
                     </div>
                  </div>
                  <div>
                     <label className="text-xs font-bold text-slate-500 uppercase">Customer Name (Optional)</label>
                     <input type="text" value={checkoutData.customerName} onChange={e => setCheckoutData({...checkoutData, customerName: e.target.value})} className="w-full mt-1 px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg outline-none" placeholder="Guest" />
                  </div>
                  <button onClick={confirmCheckout} className="w-full py-3 bg-teal-600 text-white font-bold rounded-xl shadow-lg mt-2">Confirm Payment</button>
                  <button onClick={() => setIsCheckoutOpen(false)} className="w-full py-3 bg-slate-100 text-slate-600 font-bold rounded-xl">Cancel</button>
               </div>
            </div>
         </div>
      )}

      {/* Inventory Modal */}
      {isInventoryModalOpen && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6">
               <h3 className="text-xl font-bold text-slate-800 mb-4">{editingItem ? 'Edit Item' : 'Add New Item'}</h3>
               <form onSubmit={handleSaveItem} className="space-y-4">
                  <input required type="text" placeholder="Item Name" value={itemFormData.name} onChange={e => setItemFormData({...itemFormData, name: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                  <div className="grid grid-cols-2 gap-4">
                     <input required type="number" placeholder="Price" value={itemFormData.price} onChange={e => setItemFormData({...itemFormData, price: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                     <input required type="number" placeholder="Stock" value={itemFormData.stock} onChange={e => setItemFormData({...itemFormData, stock: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                  </div>
                  <select value={itemFormData.category} onChange={e => setItemFormData({...itemFormData, category: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg">
                     {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                  </select>
                  <input type="text" placeholder="Item Code (Optional)" value={itemFormData.code} onChange={e => setItemFormData({...itemFormData, code: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg" />
                  <div className="flex gap-3 pt-2">
                     <button type="button" onClick={() => setIsInventoryModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-600 font-bold rounded-xl">Cancel</button>
                     <button type="submit" className="flex-1 py-3 bg-teal-600 text-white font-bold rounded-xl">Save Item</button>
                  </div>
               </form>
            </div>
         </div>
      )}

      {/* Receipt Modal */}
      {lastSale && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white p-4 rounded-xl shadow-2xl">
              <div id="receipt-content" className="w-[80mm] bg-white p-4 text-center text-slate-800 text-sm font-mono">
                 <h2 className="font-bold text-lg">{BRAND_NAME}</h2>
                 <p className="text-xs">{BRAND_ADDRESS}</p>
                 <p className="text-xs mb-4">{BRAND_CONTACT}</p>
                 <hr className="border-dashed border-slate-300 my-2" />
                 <div className="text-left mb-2">
                    <p>Date: {new Date(lastSale.date).toLocaleDateString()}</p>
                    <p>Bill #: {lastSale.id.slice(-6)}</p>
                    <p>Customer: {lastSale.customerName || 'Guest'}</p>
                 </div>
                 <hr className="border-dashed border-slate-300 my-2" />
                 <div className="text-left">
                    {lastSale.items.map((item, i) => (
                       <div key={i} className="flex justify-between mb-1">
                          <span>{item.name} x{item.quantity}</span>
                          <span>{(item.price * item.quantity).toLocaleString()}</span>
                       </div>
                    ))}
                 </div>
                 <hr className="border-dashed border-slate-300 my-2" />
                 <div className="flex justify-between font-bold text-lg">
                    <span>Total</span>
                    <span>{lastSale.totalAmount.toLocaleString()}</span>
                 </div>
                 <p className="text-xs mt-4">Thank you for shopping!</p>
              </div>
              <div className="flex gap-2 mt-4">
                 <button onClick={() => setLastSale(null)} className="flex-1 py-2 bg-slate-100 text-slate-600 rounded-lg font-bold">Close</button>
                 <button onClick={printReceipt} className="flex-1 py-2 bg-teal-600 text-white rounded-lg font-bold">Print</button>
              </div>
           </div>
        </div>
      )}

      {/* Security Modal */}
      {isSecurityModalOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2"><ShieldAlert className="w-5 h-5 text-teal-600" /> Security Check</h3>
              <form onSubmit={handleSecuritySubmit} className="space-y-4">
                 <input autoFocus type="password" placeholder="Admin Password" value={securityPassword} onChange={e => setSecurityPassword(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg font-bold" />
                 {securityError && <p className="text-xs text-red-500 font-bold">{securityError}</p>}
                 <div className="flex gap-3">
                    <button type="button" onClick={() => setIsSecurityModalOpen(false)} className="flex-1 py-2 bg-slate-100 text-slate-600 font-bold rounded-lg">Cancel</button>
                    <button type="submit" className="flex-1 py-2 bg-teal-600 text-white font-bold rounded-lg">Confirm</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

