    reader.onload = (evt) => {
      try {
        const data = evt.target?.result;
        if (!data) return;

        const wb = XLSX.read(data, { type: 'array' });

        // Inventory
        if (wb.Sheets["Inventory"]) {
          const invData = XLSX.utils.sheet_to_json(wb.Sheets["Inventory"]);
          if (invData.length > 0) setInventory(invData as AccessoryItem[]);
        }

        // Sales
        if (wb.Sheets["Sales"]) {
          const salesData = XLSX.utils.sheet_to_json(wb.Sheets["Sales"]);
          if (salesData.length > 0) setSales(salesData as SalesRecord[]);
        }

        // Categories
        if (wb.Sheets["Categories"]) {
          const catData = XLSX.utils.sheet_to_json(wb.Sheets["Categories"]);
          if (catData.length > 0) setCategories(catData as AccessoryCategory[]);
        }

        // Vouchers
        if (wb.Sheets["Vouchers"]) {
          const vouchRaw = XLSX.utils.sheet_to_json(wb.Sheets["Vouchers"]);
          const vouchData = vouchRaw.map((v: any) => ({
            ...v,
            items: v.items ? JSON.parse(v.items) : []
          }));
          if (vouchData.length > 0) setVouchers(vouchData as Voucher[]);
        }

