interface AccessoriesSalesDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'inventory' | 'sales-history' | 'backup' | 'settings' | 'database';

interface AccessoryItem {
  id: string;
  name: string;
  category: string;
  price: number; // Selling Price
  buyingPrice: number; // Buying Cost
  quantity: number;
  serialNumber: string; // Unique Identifier
}

interface CartItem extends AccessoryItem {
  sellQuantity: number;
  sellPrice: number;
}

interface SalesRecord {
  id: string;
  itemId: string;
  itemName: string;
  quantity: number;
  totalPrice: number;
  unitPrice: number;
  date: string;
  voucherId: string;
  status?: 'Sold' | 'Refunded';
}

interface Voucher {
  id: string;
  date: string;
  customerName: string;
  items: SalesRecord[];
  subtotal?: number;
  discountType?: 'amount' | 'percentage';
  discountValue?: number;
  totalAmount: number;
  status?: 'Completed' | 'Refunded';
}

interface AccessoryCategory {
  id: string;
  name: string;
}

