                   <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 border-4 border-red-500 text-red-500 font-bold text-6xl opacity-30 rotate-45 p-4 rounded-xl z-0 pointer-events-none">
