import React, { useState, useEffect } from 'react';
import { useReactToPrint } from 'react-to-print';
import * as XLSX from 'xlsx';

interface Settings {
    footerText: string;
}

interface AccessorySalesData {
    // Define your accessory sales data structure here
}

interface Props {
    settings: Settings;
    salesData: AccessorySalesData[]; // Assuming an array of sales data
}

const AccessoriesSalesDashboard: React.FC<Props> = ({ settings, salesData }) => {
    const [isPrinting, setIsPrinting] = useState(false);
    const [excelData, setExcelData] = useState<any[]>([]); // Replace 'any' with the appropriate type

    const componentRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        // Prepare data for Excel export (similar to the previous implementation)
        const dataForExcel = salesData.map((sale) => {
            // Map your sales data to the structure expected by XLSX
            return {
                // Example: replace with actual data mapping
                'Column 1': 'Example Value',
                'Column 2': 123,
                // ... map other fields
            };
        });
        setExcelData(dataForExcel);
    }, [salesData]); // Re-run effect when salesData changes

    const handleExcelExport = () => {
        if (!excelData || excelData.length === 0) {
            console.warn('No data to export.');
            return;
        }

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(excelData);
        XLSX.utils.book_append_sheet(wb, ws, 'SalesData');
        XLSX.writeFile(wb, 'AccessoriesSalesData.xlsx');
    };

    const handlePrint = useReactToPrint({
