                   <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                   <input 
                     type="password"
                     autoFocus
                     required
                     className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 text-slate-800 font-bold"
                     placeholder="Enter security key"
                     value={inventorySecurityKey}
                     onChange={e => setInventorySecurityKey(e.target.value)}
                   />
                 </div>
               </div>

               {inventorySecurityError && (
                 <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl font-bold text-center animate-fade-in border border-red-100">
                   {inventorySecurityError}
                 </div>
               )}

               <div className="pt-2 flex gap-3">
                 <button 
                   type="button" 
                   onClick={() => setIsInventorySecurityOpen(false)}
                   className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-colors"
                 >
                   Cancel
                 </button>
                 <button 
                   type="submit"
                   className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all"
                 >
                   Confirm
                 </button>
               </div>
             </form>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Wrench, 
  PlusCircle, 
  Save, 
  LogOut, 
  Search, 
  Smartphone, 
  Filter, 
  CheckCircle, 
  Clock, 
  AlertCircle, 
  X, 
  Printer, 
  Edit, 
  Trash2,
  Lock,
  Eye,
  Settings,
  Database,
  Upload,
  Download,
  Calendar as CalendarIcon,
  ShoppingBag
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup, getStorageUsage } from '../services/storage';

interface RepairDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'tickets' | 'create-ticket' | 'backup' | 'database';
type TicketStatus = 'Pending' | 'In Progress' | 'Completed' | 'Delivered' | 'Cancelled';

interface RepairTicket {
  id: string;
  customerName: string;
  phoneNumber: string;
  date: string;
  deviceBrand: string;
  deviceModel: string;
  imei: string;
  errorType: string;
  screenLock: { type: string; value: string };
  accessories: { [key: string]: boolean };
  note: string;
  estimatedCost: string;
  finalCost: string;
  status: TicketStatus;
  completedDate?: string;
}

const DEFAULT_TICKETS: RepairTicket[] = [];

const ACCESSORY_OPTIONS = ['Sim Card', 'Memory Card', 'Phone Case', 'Box', 'Charger'];

export const RepairDashboard: React.FC<RepairDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- State ---
  const [tickets, setTickets] = useState<RepairTicket[]>(() => 
    loadData(StorageKeys.TICKETS, DEFAULT_TICKETS)
  );

  useEffect(() => {
    saveData(StorageKeys.TICKETS, tickets);
  }, [tickets]);

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<TicketStatus | 'All'>('All');

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    customerName: '',
    phoneNumber: '',
    deviceBrand: '',
    deviceModel: '',
    imei: '',
    errorType: '',
    screenLockType: 'None',
    screenLockValue: '',
    accessories: {} as { [key: string]: boolean },
    note: '',
    estimatedCost: '',
    finalCost: '',
    status: 'Pending' as TicketStatus,
    date: new Date().toISOString().split('T')[0]
  });

  // Modal States
  const [viewTicket, setViewTicket] = useState<RepairTicket | null>(null);
  const [isSecurityModalOpen, setIsSecurityModalOpen] = useState(false);
  const [securityAction, setSecurityAction] = useState<'delete' | 'edit_status' | null>(null);
  const [securityTargetId, setSecurityTargetId] = useState<string | null>(null);
  const [securityPassword, setSecurityPassword] = useState('');
  const [securityError, setSecurityError] = useState('');
  const [securityNewStatus, setSecurityNewStatus] = useState<TicketStatus | null>(null);

  // --- Handlers ---

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleAccessoryChange = (acc: string) => {
    setFormData(prev => ({
      ...prev,
      accessories: { ...prev.accessories, [acc]: !prev.accessories[acc] }
    }));
  };

  const handleSaveTicket = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setTickets(prev => prev.map(t => {
        if (t.id === editingId) {
           return {
             ...t,
             customerName: formData.customerName,
             phoneNumber: formData.phoneNumber,
             deviceBrand: formData.deviceBrand,
             deviceModel: formData.deviceModel,
             imei: formData.imei,
             errorType: formData.errorType,
             screenLock: { type: formData.screenLockType, value: formData.screenLockValue },
             accessories: formData.accessories,
             note: formData.note,
             estimatedCost: formData.estimatedCost,
             finalCost: formData.finalCost,
             status: formData.status,
             date: formData.date
           };
        }
        return t;
      }));
      alert('Repair Ticket updated successfully!');
      setEditingId(null);
    } else {
      const newTicket: RepairTicket = {
        id: `R-${Date.now().toString().slice(-6)}`,
        customerName: formData.customerName,
        phoneNumber: formData.phoneNumber,
        date: formData.date,
        deviceBrand: formData.deviceBrand,
        deviceModel: formData.deviceModel,
        imei: formData.imei,
        errorType: formData.errorType,
        screenLock: { type: formData.screenLockType, value: formData.screenLockValue },
        accessories: formData.accessories,
        note: formData.note,
        estimatedCost: formData.estimatedCost,
        finalCost: formData.finalCost,
        status: 'Pending'
      };
      setTickets(prev => [newTicket, ...prev]);
      alert('New Repair Ticket created!');
    }

    resetForm();
    setCurrentView('tickets');
  };

  const resetForm = () => {
    setFormData({
        customerName: '',
        phoneNumber: '',
        deviceBrand: '',
        deviceModel: '',
        imei: '',
        errorType: '',
        screenLockType: 'None',
        screenLockValue: '',
        accessories: {},
        note: '',
        estimatedCost: '',
        finalCost: '',
        status: 'Pending',
        date: new Date().toISOString().split('T')[0]
    });
    setEditingId(null);
  };

  const handleEditClick = (ticket: RepairTicket) => {
     setEditingId(ticket.id);
     setFormData({
        customerName: ticket.customerName,
        phoneNumber: ticket.phoneNumber,
        deviceBrand: ticket.deviceBrand,
        deviceModel: ticket.deviceModel,
        imei: ticket.imei,
        errorType: ticket.errorType,
        screenLockType: ticket.screenLock.type,
        screenLockValue: ticket.screenLock.value,
        accessories: ticket.accessories,
        note: ticket.note,
        estimatedCost: ticket.estimatedCost,
        finalCost: ticket.finalCost,
        status: ticket.status,
        date: ticket.date
     });
     setCurrentView('create-ticket');
  };

  const handleDeleteClick = (id: string) => {
     setSecurityAction('delete');
     setSecurityTargetId(id);
     setIsSecurityModalOpen(true);
  };

  const handleStatusChangeClick = (ticket: RepairTicket, newStatus: TicketStatus) => {
     // If changing to Completed or Delivered, we might want security check or just confirmation
     setTickets(prev => prev.map(t => t.id === ticket.id ? { ...t, status: newStatus } : t));
  };

  const handleSecuritySubmit = (e: React.FormEvent) => {
     e.preventDefault();
     if (securityPassword === '1471656') {
        if (securityAction === 'delete' && securityTargetId) {
           setTickets(prev => prev.filter(t => t.id !== securityTargetId));
        }
        setIsSecurityModalOpen(false);
        setSecurityPassword('');
        setSecurityAction(null);
        setSecurityTargetId(null);
     } else {
        setSecurityError('Incorrect Password');
     }
  };

  const handlePrintTicket = () => {
     const element = document.getElementById('repair-ticket-print');
     if (element) {
        const opt = {
           margin: 0.2,
           filename: `Repair_Ticket_${viewTicket?.id}.pdf`,
           image: { type: 'jpeg', quality: 0.98 },
           html2canvas: { scale: 2, useCORS: true },
           jsPDF: { unit: 'in', format: 'a5', orientation: 'portrait' }
        };
        html2pdf().set(opt).from(element).save();
     }
  };

  const handleBackupNow = () => {
    createFullBackup('HHS_REPAIR');
  };

  const handleAutoBackupAndLogout = () => {
    createFullBackup('HHS_REPAIR');
    setTimeout(() => {
      onLogout();
    }, 500);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target?.result as string;
        const data = JSON.parse(content);
        if (data.tickets && Array.isArray(data.tickets)) {
          setTickets(data.tickets);
          alert('Repair data restored successfully!');
        } else {
          alert('Invalid backup file structure.');
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (error) {
        alert('Error parsing backup file.');
      }
    };
    reader.readAsText(file);
  };

  // --- Filtering ---
  const filteredTickets = tickets.filter(t => {
     const matchesSearch = t.customerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           t.phoneNumber.includes(searchTerm) || 
                           t.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           t.deviceModel.toLowerCase().includes(searchTerm.toLowerCase());
     const matchesStatus = statusFilter === 'All' || t.status === statusFilter;
     return matchesSearch && matchesStatus;
  });

  // --- Stats ---
  const pendingCount = tickets.filter(t => t.status === 'Pending').length;
  const inProgressCount = tickets.filter(t => t.status === 'In Progress').length;
  const completedCount = tickets.filter(t => t.status === 'Completed' || t.status === 'Delivered').length;
  const totalRevenue = tickets.filter(t => t.status === 'Delivered').reduce((acc, t) => acc + (parseFloat(t.finalCost) || 0), 0);


  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tickets', label: 'All Tickets', icon: Wrench },
    { id: 'create-ticket', label: 'Create Ticket', icon: PlusCircle },
    { id: 'backup', label: 'Backup & Restore', icon: Save },
    { id: 'database', label: 'Database Status', icon: Database },
  ];

  const renderContent = () => {
    switch (currentView) {
       case 'dashboard':
          return (
             <div className="space-y-6 animate-fade-in">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                   <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                      <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                         <Clock className="w-24 h-24 text-orange-600" />
                      </div>
                      <p className="text-slate-500 text-sm font-medium">Pending</p>
                      <h3 className="text-3xl font-bold text-orange-600 mt-2">{pendingCount}</h3>
                   </div>
                   <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                      <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                         <Wrench className="w-24 h-24 text-blue-600" />
                      </div>
                      <p className="text-slate-500 text-sm font-medium">In Progress</p>
                      <h3 className="text-3xl font-bold text-blue-600 mt-2">{inProgressCount}</h3>
                   </div>
                   <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                      <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                         <CheckCircle className="w-24 h-24 text-emerald-600" />
                      </div>
                      <p className="text-slate-500 text-sm font-medium">Completed</p>
                      <h3 className="text-3xl font-bold text-emerald-600 mt-2">{completedCount}</h3>
                   </div>
                   <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                      <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                         <ShoppingBag className="w-24 h-24 text-indigo-600" />
                      </div>
                      <p className="text-slate-500 text-sm font-medium">Total Revenue</p>
                      <h3 className="text-2xl font-bold text-indigo-600 mt-2">{totalRevenue.toLocaleString()} K</h3>
                   </div>
                </div>

                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                   <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                     <h3 className="font-bold text-slate-800">Recent Tickets</h3>
                     <button onClick={() => setCurrentView('tickets')} className="text-indigo-600 text-sm font-medium hover:underline">View All</button>
                   </div>
                   <div className="p-0">
                      <table className="w-full text-left">
                         <thead className="bg-slate-50 text-xs uppercase text-slate-500 font-bold">
                            <tr>
                               <th className="p-4">Ticket ID</th>
                               <th className="p-4">Customer</th>
                               <th className="p-4">Device</th>
                               <th className="p-4">Issue</th>
                               <th className="p-4 text-center">Status</th>
                            </tr>
                         </thead>
                         <tbody className="divide-y divide-slate-100">
                            {tickets.slice(0, 5).map(t => (
                               <tr key={t.id} className="hover:bg-slate-50 cursor-pointer" onClick={() => setViewTicket(t)}>
                                  <td className="p-4 font-mono text-xs font-bold text-indigo-600">{t.id}</td>
                                  <td className="p-4">
                                     <div className="font-bold text-slate-800 text-sm">{t.customerName}</div>
                                     <div className="text-xs text-slate-500">{t.phoneNumber}</div>
                                  </td>
                                  <td className="p-4 text-sm text-slate-700">{t.deviceBrand} {t.deviceModel}</td>
                                  <td className="p-4 text-sm text-red-500 font-medium">{t.errorType}</td>
                                  <td className="p-4 text-center">
                                     <span className={`px-2 py-1 rounded text-xs font-bold ${
                                        t.status === 'Pending' ? 'bg-orange-100 text-orange-700' :
                                        t.status === 'In Progress' ? 'bg-blue-100 text-blue-700' :
                                        t.status === 'Completed' ? 'bg-emerald-100 text-emerald-700' :
                                        'bg-slate-100 text-slate-700'
                                     }`}>
                                        {t.status}
                                     </span>
                                  </td>
                               </tr>
                            ))}
                         </tbody>
                      </table>
                   </div>
                </div>
             </div>
          );

       case 'tickets':
          return (
             <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full animate-fade-in">
                <div className="p-6 border-b border-slate-100">
                  <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                     <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                        <Wrench className="w-5 h-5 text-indigo-600" /> Service Tickets
                     </h3>
                     <div className="flex gap-4">
                        <div className="relative">
                           <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
