               <button onClick={() => setIsSecurityModalOpen(false)} className="text-white/60 hover:text-white"><X className="w-6 h-6" /></button>
             </div>
             <form onSubmit={handleSecuritySubmit} className="p-6 space-y-4">
               <p className="text-sm text-slate-500 text-center mb-4">Enter password to confirm action.</p>
               <div>
                 <input 
                    type="password" 
                    autoFocus 
                    required 
                    className="w-full pl-4 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 text-slate-800 font-bold text-center"
                    placeholder="Password"
                    value={securityPassword}
                    onChange={e => setSecurityPassword(e.target.value)}
                 />
               </div>
               {securityError && (
                 <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl font-bold text-center animate-fade-in border border-red-100">{securityError}</div>
               )}
               <div className="pt-2 flex gap-3">
                 <button type="button" onClick={() => setIsSecurityModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200">Cancel</button>
                 <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700">Confirm</button>
               </div>
             </form>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Wrench, 
  PlusCircle, 
  Save, 
  LogOut, 
  Search, 
  Clock, 
  CheckCircle, 
  XCircle, 
  AlertCircle, 
  Printer,
  Smartphone,
  User,
  FileText,
  Edit,
  Trash2,
  Eye,
  X,
  Filter,
  Lock,
  Unlock,
  Cpu,
  Hash,
  Download,
  Upload,
  ClipboardList
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup } from '../services/storage';

interface RepairDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'tickets' | 'new-ticket' | 'backup';
type RepairStatus = 'Pending' | 'In Progress' | 'Completed' | 'Delivered' | 'Cancelled';

interface RepairTicket {
  id: string;
  customerName: string;
  phoneNumber: string;
  deviceBrand: string;
  deviceModel: string;
  imei: string;
  errorType: string;
  screenLock: {
    type: 'Pattern' | 'PIN' | 'Password' | 'None';
    value: string;
  };
  accessories: {
    [key: string]: boolean;
  };
  estimatedCost: number;
  finalCost: number;
  status: RepairStatus;
  date: string;
  note: string;
  deliveredDate?: string;
}

const DEFAULT_TICKETS: RepairTicket[] = [];

export const RepairDashboard: React.FC<RepairDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [tickets, setTickets] = useState<RepairTicket[]>(() => 
    loadData(StorageKeys.TICKETS, DEFAULT_TICKETS)
  );

  useEffect(() => {
    saveData(StorageKeys.TICKETS, tickets);
  }, [tickets]);

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<RepairStatus | 'All'>('All');

  // Form State
  const [editingTicketId, setEditingTicketId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    customerName: '',
    phoneNumber: '',
    deviceBrand: '',
    deviceModel: '',
    imei: '',
    errorType: '',
    lockType: 'None',
    lockValue: '',
    accessories: {
      sim: false,
      sdCard: false,
      battery: false,
      cover: false
    },
    estimatedCost: '',
    note: ''
  });

  // View/Modal State
  const [viewTicket, setViewTicket] = useState<RepairTicket | null>(null);
  const [statusModalOpen, setStatusModalOpen] = useState(false);
  const [statusActionTicket, setStatusActionTicket] = useState<RepairTicket | null>(null);
  const [newStatus, setNewStatus] = useState<RepairStatus>('Pending');
  const [statusNote, setStatusNote] = useState('');
  const [finalCost, setFinalCost] = useState('');

  // --- Handlers ---

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleAccessoryChange = (key: string) => {
    setFormData(prev => ({
      ...prev,
      accessories: {
        ...prev.accessories,
        [key]: !prev.accessories[key as keyof typeof prev.accessories]
      }
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingTicketId) {
      setTickets(prev => prev.map(t => {
        if (t.id === editingTicketId) {
          return {
            ...t,
            customerName: formData.customerName,
            phoneNumber: formData.phoneNumber,
            deviceBrand: formData.deviceBrand,
            deviceModel: formData.deviceModel,
            imei: formData.imei,
            errorType: formData.errorType,
            screenLock: {
              type: formData.lockType as any,
              value: formData.lockValue
            },
            accessories: formData.accessories,
            estimatedCost: Number(formData.estimatedCost),
            note: formData.note
          };
        }
        return t;
      }));
      alert('Ticket updated successfully');
      setEditingTicketId(null);
    } else {
      const newTicket: RepairTicket = {
        id: `REP-${Date.now().toString().slice(-6)}`,
        date: new Date().toISOString().split('T')[0],
        status: 'Pending',
        finalCost: 0,
        customerName: formData.customerName,
        phoneNumber: formData.phoneNumber,
        deviceBrand: formData.deviceBrand,
        deviceModel: formData.deviceModel,
        imei: formData.imei,
        errorType: formData.errorType,
        screenLock: {
          type: formData.lockType as any,
          value: formData.lockValue
        },
        accessories: formData.accessories,
        estimatedCost: Number(formData.estimatedCost),
        note: formData.note
      };
      setTickets(prev => [newTicket, ...prev]);
      alert('New ticket created successfully');
    }

    // Reset Form
    setFormData({
      customerName: '',
      phoneNumber: '',
      deviceBrand: '',
      deviceModel: '',
      imei: '',
      errorType: '',
      lockType: 'None',
      lockValue: '',
      accessories: { sim: false, sdCard: false, battery: false, cover: false },
      estimatedCost: '',
      note: ''
    });
    setCurrentView('tickets');
  };

  const handleEdit = (ticket: RepairTicket) => {
    setEditingTicketId(ticket.id);
    setFormData({
      customerName: ticket.customerName,
      phoneNumber: ticket.phoneNumber,
      deviceBrand: ticket.deviceBrand,
      deviceModel: ticket.deviceModel,
      imei: ticket.imei,
      errorType: ticket.errorType,
      lockType: ticket.screenLock.type,
      lockValue: ticket.screenLock.value,
      accessories: { ...ticket.accessories, sim: ticket.accessories.sim || false, sdCard: ticket.accessories.sdCard || false, battery: ticket.accessories.battery || false, cover: ticket.accessories.cover || false },
      estimatedCost: ticket.estimatedCost.toString(),
      note: ticket.note
    });
    setCurrentView('new-ticket');
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this ticket?')) {
      setTickets(prev => prev.filter(t => t.id !== id));
    }
  };

  const openStatusModal = (ticket: RepairTicket) => {
    setStatusActionTicket(ticket);
    setNewStatus(ticket.status);
    setStatusNote(ticket.note || '');
    setFinalCost(ticket.finalCost ? ticket.finalCost.toString() : ticket.estimatedCost.toString());
    setStatusModalOpen(true);
  };

  const handleStatusUpdate = () => {
    if (!statusActionTicket) return;

    setTickets(prev => prev.map(t => {
      if (t.id === statusActionTicket.id) {
        return {
          ...t,
          status: newStatus,
          note: statusNote,
          finalCost: Number(finalCost),
          deliveredDate: newStatus === 'Delivered' && t.status !== 'Delivered' ? new Date().toISOString().split('T')[0] : t.deliveredDate
        };
      }
      return t;
    }));
    setStatusModalOpen(false);
    setStatusActionTicket(null);
  };

  const handlePrint = () => {
    const element = document.getElementById('print-ticket');
    if (element) {
      const opt = {
        margin: 0,
        filename: `Repair_Ticket_${viewTicket?.id}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a5', orientation: 'portrait' }
      };

      const originalStyle = element.getAttribute('style');
      element.style.display = 'block'; // Ensure it's visible for capture

      html2pdf().set(opt).from(element).save().then(() => {
         if (originalStyle) element.setAttribute('style', originalStyle);
      });
    }
  };

  const handleAutoBackupAndLogout = () => {
    createFullBackup('HHS_REPAIR');
    setTimeout(() => {
      onLogout();
    }, 500);
  };

  const handleBackupNow = () => {
    createFullBackup('HHS_REPAIR');
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target?.result as string;
        const data = JSON.parse(content);
        if (data.tickets && Array.isArray(data.tickets)) {
          setTickets(data.tickets);
          alert('Repair data restored successfully!');
        } else {
          alert('Invalid backup file structure.');
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (error) {
        alert('Error parsing backup file.');
      }
    };
    reader.readAsText(file);
  };

  // --- Filtering ---
  const filteredTickets = tickets.filter(t => {
    const matchesSearch = t.customerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.phoneNumber.includes(searchTerm) ||
                          t.deviceModel.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All' || t.status === statusFilter;
    return matchesSearch && matchesStatus;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // --- Stats ---
  const pendingCount = tickets.filter(t => t.status === 'Pending').length;
  const inProgressCount = tickets.filter(t => t.status === 'In Progress').length;
  const completedCount = tickets.filter(t => t.status === 'Completed').length;
  const deliveredCount = tickets.filter(t => t.status === 'Delivered').length;

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tickets', label: 'Ticket List', icon: ClipboardList },
    { id: 'new-ticket', label: 'New Ticket', icon: PlusCircle },
    { id: 'backup', label: 'Data Backup', icon: Save },
  ];

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-fade-in">
             <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center text-center">
                   <div className="p-3 bg-orange-100 rounded-full text-orange-600 mb-3"><Clock className="w-6 h-6" /></div>
                   <h3 className="text-2xl font-bold text-slate-800">{pendingCount}</h3>
                   <p className="text-xs font-bold text-slate-500 uppercase">Pending</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center text-center">
                   <div className="p-3 bg-blue-100 rounded-full text-blue-600 mb-3"><Wrench className="w-6 h-6" /></div>
                   <h3 className="text-2xl font-bold text-slate-800">{inProgressCount}</h3>
                   <p className="text-xs font-bold text-slate-500 uppercase">In Progress</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center text-center">
                   <div className="p-3 bg-emerald-100 rounded-full text-emerald-600 mb-3"><CheckCircle className="w-6 h-6" /></div>
                   <h3 className="text-2xl font-bold text-slate-800">{completedCount}</h3>
                   <p className="text-xs font-bold text-slate-500 uppercase">Completed</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex flex-col items-center justify-center text-center">
                   <div className="p-3 bg-slate-100 rounded-full text-slate-600 mb-3"><User className="w-6 h-6" /></div>
                   <h3 className="text-2xl font-bold text-slate-800">{deliveredCount}</h3>
                   <p className="text-xs font-bold text-slate-500 uppercase">Delivered</p>
                </div>
             </div>

             <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Recent Tickets</h3>
                  <button onClick={() => setCurrentView('tickets')} className="text-indigo-600 text-sm font-medium hover:underline">View All</button>
                </div>
                <div className="p-0">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-xs uppercase text-slate-500 font-bold">
                         <tr>
                            <th className="p-4">Ticket ID</th>
                            <th className="p-4">Customer</th>
                            <th className="p-4">Device</th>
                            <th className="p-4">Status</th>
                            <th className="p-4 text-right">Cost</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {tickets.slice(0, 5).map(t => (
                            <tr key={t.id} className="hover:bg-slate-50 cursor-pointer" onClick={() => setViewTicket(t)}>
                               <td className="p-4 font-mono text-xs font-bold text-indigo-600">{t.id}</td>
                               <td className="p-4 font-bold text-slate-800 text-sm">{t.customerName}</td>
                               <td className="p-4 text-sm text-slate-600">{t.deviceModel} <span className="text-xs text-red-500 block">{t.errorType}</span></td>
                               <td className="p-4"><span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                                 t.status === 'Pending' ? 'bg-orange-100 text-orange-600' :
                                 t.status === 'In Progress' ? 'bg-blue-100 text-blue-600' :
                                 t.status === 'Completed' ? 'bg-emerald-100 text-emerald-600' :
                                 'bg-slate-100 text-slate-600'
                               }`}>{t.status}</span></td>
                               <td className="p-4 text-right font-bold text-slate-700">{t.finalCost > 0 ? t.finalCost.toLocaleString() : t.estimatedCost.toLocaleString()}</td>
                            </tr>
                         ))}
                         {tickets.length === 0 && (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400 italic">No tickets yet.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        );

      case 'tickets':
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full animate-fade-in">
             <div className="p-6 border-b border-slate-100">
               <div className="flex justify-between items-center mb-4">
                  <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                     <ClipboardList className="w-5 h-5 text-indigo-600" /> Repair Tickets
                  </h3>
                  <button onClick={() => setCurrentView('new-ticket')} className="px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-indigo-700">
                      <PlusCircle className="w-4 h-4" /> New Ticket
                  </button>
               </div>

               <div className="flex flex-wrap gap-4">
                  <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Search tickets..." 
                      className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-indigo-500"
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                  </div>
                  <select 
                     className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none"
                     value={statusFilter}
                     onChange={e => setStatusFilter(e.target.value as any)}
                  >
                     <option value="All">All Status</option>
                     <option value="Pending">Pending</option>
                     <option value="In Progress">In Progress</option>
                     <option value="Completed">Completed</option>
                     <option value="Delivered">Delivered</option>
                     <option value="Cancelled">Cancelled</option>
                  </select>
               </div>
             </div>

             <div className="flex-1 overflow-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 sticky top-0 z-10">
                      <tr className="text-slate-500 text-xs uppercase font-bold tracking-wider">
                         <th className="p-4">Ticket</th>
                         <th className="p-4">Customer</th>
                         <th className="p-4">Device / Error</th>
                         <th className="p-4 text-center">Status</th>
                         <th className="p-4 text-right">Actions</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {filteredTickets.map(t => (
                         <tr key={t.id} className="hover:bg-slate-50">
                            <td className="p-4">
                               <div className="font-mono text-xs font-bold text-indigo-600">{t.id}</div>
                               <div className="text-[10px] text-slate-400">{t.date}</div>
                            </td>
                            <td className="p-4">
                               <div className="font-bold text-slate-800 text-sm">{t.customerName}</div>
                               <div className="text-xs text-slate-500">{t.phoneNumber}</div>
                            </td>
                            <td className="p-4">
                               <div className="font-bold text-slate-700 text-sm">{t.deviceModel}</div>
                               <div className="text-xs text-red-500 font-medium">{t.errorType}</div>
                            </td>
                            <td className="p-4 text-center">
                               <button 
                                 onClick={() => openStatusModal(t)}
                                 className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase transition-all hover:scale-105 ${
                                    t.status === 'Pending' ? 'bg-orange-100 text-orange-600' :
                                    t.status === 'In Progress' ? 'bg-blue-100 text-blue-600' :
                                    t.status === 'Completed' ? 'bg-emerald-100 text-emerald-600' :
                                    t.status === 'Delivered' ? 'bg-slate-200 text-slate-600' :
                                    'bg-red-100 text-red-600'
                                 }`}
                               >
                                  {t.status}
                               </button>
                            </td>
                            <td className="p-4 text-right">
                               <div className="flex justify-end gap-1">
                                  <button onClick={() => setViewTicket(t)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg">
                                     <Eye className="w-4 h-4" />
                                  </button>
                                  <button onClick={() => handleEdit(t)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg">
                                     <Edit className="w-4 h-4" />
                                  </button>
                                  <button onClick={() => handleDelete(t.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg">
                                     <Trash2 className="w-4 h-4" />
                                  </button>
                               </div>
                            </td>
                         </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );

      case 'new-ticket':
        return (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 h-full flex flex-col animate-fade-in max-w-4xl mx-auto w-full">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
               <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                  <PlusCircle className="w-5 h-5 text-indigo-600" /> {editingTicketId ? 'Edit Ticket' : 'Create New Ticket'}
               </h3>
               {editingTicketId && (
                 <button onClick={() => { setEditingTicketId(null); setCurrentView('tickets'); }} className="text-red-500 text-sm font-bold hover:underline">Cancel Edit</button>
               )}
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-6">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Customer Info */}
                  <div className="space-y-4">
                     <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider border-b border-slate-100 pb-2">Customer Info</h4>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Customer Name</label>
                        <div className="relative">
                           <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                           <input required type="text" className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-lg text-sm" placeholder="Enter name" value={formData.customerName} onChange={e => handleInputChange('customerName', e.target.value)} />
                        </div>
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Phone Number</label>
                        <div className="relative">
                           <Smartphone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                           <input required type="tel" className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-lg text-sm" placeholder="09..." value={formData.phoneNumber} onChange={e => handleInputChange('phoneNumber', e.target.value)} />
                        </div>
                     </div>
                  </div>

                  {/* Device Info */}
                  <div className="space-y-4">
                     <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider border-b border-slate-100 pb-2">Device Info</h4>
                     <div className="grid grid-cols-2 gap-4">
                        <div>
                           <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Brand</label>
                           <input required type="text" className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm" placeholder="e.g. Samsung" value={formData.deviceBrand} onChange={e => handleInputChange('deviceBrand', e.target.value)} />
                        </div>
                        <div>
                           <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Model</label>
                           <input required type="text" className="w-full px-3 py-2 border border-slate-200 rounded-lg text-sm" placeholder="e.g. A12" value={formData.deviceModel} onChange={e => handleInputChange('deviceModel', e.target.value)} />
                        </div>
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">IMEI (Optional)</label>
                        <div className="relative">
                           <Hash className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                           <input type="text" className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-lg text-sm font-mono" placeholder="IMEI / Serial" value={formData.imei} onChange={e => handleInputChange('imei', e.target.value)} />
                        </div>
                     </div>
                  </div>
               </div>

               {/* Issue & Security */}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                     <h4 className="font-bold text-red-600 text-sm uppercase tracking-wider border-b border-red-100 pb-2">Issue & Repair</h4>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Reported Error</label>
