        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const json = XLSX.utils.sheet_to_json(worksheet);

        const newItems: AccessoryItem[] = [];
        let successCount = 0;

        json.forEach((row: any) => {
           // Basic validation and mapping
           const name = row['Item Name'] || row['Name'] || row['name'] || row['Item'] || row['item'];
           const category = row['Category'] || row['category'] || 'General';
           const price = row['Selling Price'] || row['Price'] || row['price'] || row['sellingPrice'];
           const buyingPrice = row['Buying Price'] || row['buyingPrice'] || row['Cost'] || row['cost'] || 0;
           const quantity = row['Quantity'] || row['Qty'] || row['quantity'] || row['stock'] || 0;
           const serialNumber = row['Serial Number'] || row['SerialNo'] || row['serialNumber'] || row['SN'] || row['sn'] || '';

           if (name) {
              newItems.push({
                 id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
                 name: String(name),
                 category: String(category),
                 price: Number(price) || 0,
                 buyingPrice: Number(buyingPrice) || 0,
                 quantity: Number(quantity) || 0,
                 serialNumber: String(serialNumber)
              });
              successCount++;
           }
        });

        if (successCount > 0) {
           setInventory(prev => [...prev, ...newItems]);
           alert(`Successfully imported ${successCount} items from Excel.`);
        } else {
           alert('No valid items found. Please check column headers (e.g., Item Name, Price, Qty).');
        }
