import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  PlusCircle, 
  Save, 
  LogOut, 
  Search, 
  Headphones, 
  DollarSign, 
  TrendingUp, 
  Download, 
  Upload, 
  Filter, 
  Edit, 
  Trash2, 
  Minus, 
  Plus, 
  Calendar as CalendarIcon, 
  ShoppingBag,
  Printer,
  Settings,
  X,
  Check,
  Barcode,
  MapPin,
  Phone,
  FileText,
  User,
  ShieldAlert,
  Lock,
  RotateCcw,
  Database,
  Percent,
  RefreshCw,
  FileSpreadsheet,
  Zap,
  Layers,
  Copy
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
// @ts-ignore
import * as XLSX from 'xlsx';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup, getStorageUsage } from '../services/storage';

interface AccessoriesSalesDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'inventory' | 'one-click-inventory' | 'sales-history' | 'backup' | 'settings' | 'database';

interface AccessoryItem {
  id: string;
  name: string;
  category: string;
  price: number; // Selling Price
  buyingPrice: number; // Buying Cost
  quantity: number;
  serialNumber: string; // Unique Identifier
}

interface CartItem extends AccessoryItem {
  sellQuantity: number;
  sellPrice: number;
}

interface SalesRecord {
  id: string;
  itemId: string;
  itemName: string;
  quantity: number;
  totalPrice: number;
  unitPrice: number;
  date: string;
  voucherId: string;
  status?: 'Sold' | 'Refunded';
}

interface Voucher {
  id: string;
  date: string;
  customerName: string;
  items: SalesRecord[];
  subtotal?: number;
  discountType?: 'amount' | 'percentage';
  discountValue?: number;
  totalAmount: number;
  status?: 'Completed' | 'Refunded';
}

interface AccessoryCategory {
  id: string;
  name: string;
}

const DEFAULT_INVENTORY: AccessoryItem[] = [
  { id: '1', name: 'USB-C Cable', category: 'Cables', price: 5000, buyingPrice: 2000, quantity: 20, serialNumber: 'CBL001' },
  { id: '2', name: 'iPhone 14 Case', category: 'Cases', price: 8000, buyingPrice: 4000, quantity: 15, serialNumber: 'CSE002' },
  { id: '3', name: 'Bluetooth Earbuds', category: 'Audio', price: 25000, buyingPrice: 15000, quantity: 5, serialNumber: 'AUD003' }
];

const DEFAULT_CATEGORIES: AccessoryCategory[] = [
  { id: 'c1', name: 'Cables' },
  { id: 'c2', name: 'Cases' },
  { id: 'c3', name: 'Audio' },
  { id: 'c4', name: 'Chargers' },
  { id: 'c5', name: 'Screen Guards' }
];

export const AccessoriesSalesDashboard: React.FC<AccessoriesSalesDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const excelInputRef = useRef<HTMLInputElement>(null);

  // --- State ---
  const [inventory, setInventory] = useState<AccessoryItem[]>(() => 
    loadData(StorageKeys.ACCESSORIES_INVENTORY, DEFAULT_INVENTORY)
  );

  const [sales, setSales] = useState<SalesRecord[]>(() => 
    loadData(StorageKeys.ACCESSORIES_SALES, [])
  );

  const [vouchers, setVouchers] = useState<Voucher[]>(() => 
    loadData(StorageKeys.ACCESSORIES_VOUCHERS, [])
  );

  const [categories, setCategories] = useState<AccessoryCategory[]>(() => 
    loadData(StorageKeys.ACCESSORIES_CATEGORIES, DEFAULT_CATEGORIES)
  );

  const [settings, setSettings] = useState(() => 
    loadData(StorageKeys.ACCESSORIES_SETTINGS, { 
      footerText: "Thank you for shopping with us!" 
    })
  );

  useEffect(() => {
    saveData(StorageKeys.ACCESSORIES_INVENTORY, inventory);
  }, [inventory]);

  useEffect(() => {
    saveData(StorageKeys.ACCESSORIES_SALES, sales);
  }, [sales]);

  useEffect(() => {
    saveData(StorageKeys.ACCESSORIES_VOUCHERS, vouchers);
  }, [vouchers]);

  useEffect(() => {
    saveData(StorageKeys.ACCESSORIES_CATEGORIES, categories);
  }, [categories]);

  useEffect(() => {
    saveData(StorageKeys.ACCESSORIES_SETTINGS, settings);
  }, [settings]);

  // Form State for Adding/Editing Item
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<AccessoryItem | null>(null);
  const [isAddStockMode, setIsAddStockMode] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    price: '',
    buyingPrice: '0',
    quantity: '',
    serialNumber: ''
  });

  // One Click Inventory State
  const [oneClickCategory, setOneClickCategory] = useState('');
  const [oneClickData, setOneClickData] = useState({
    serialNumber: '',
    name: '',
    buyingPrice: '',
    price: '',
    quantity: ''
  });
  const oneClickSerialRef = useRef<HTMLInputElement>(null);

  // Bulk Mode State
  const [isBulkMode, setIsBulkMode] = useState(false);
  const [bulkItems, setBulkItems] = useState([
    { serialNumber: '', name: '', buyingPrice: '', price: '', quantity: '' }
  ]);

  // Cart & Voucher State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [voucherCustomerName, setVoucherCustomerName] = useState('');

  // Discount State
  const [discountType, setDiscountType] = useState<'amount' | 'percentage'>('amount');
  const [discountValue, setDiscountValue] = useState('');

  // Viewing History Voucher
  const [selectedVoucher, setSelectedVoucher] = useState<Voucher | null>(null);

  // Category Management State
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<AccessoryCategory | null>(null);
  const [categoryFormName, setCategoryFormName] = useState('');

  // Security & Refund State
  const [isSecurityModalOpen, setIsSecurityModalOpen] = useState(false);
  const [securityPassword, setSecurityPassword] = useState('');
  const [securityError, setSecurityError] = useState('');
  const [voucherToRefund, setVoucherToRefund] = useState<Voucher | null>(null);

  // Inventory Security State
  const [isInventorySecurityOpen, setIsInventorySecurityOpen] = useState(false);
  const [inventorySecurityKey, setInventorySecurityKey] = useState('');
  const [inventorySecurityError, setInventorySecurityError] = useState('');
  const [inventoryAction, setInventoryAction] = useState<'edit' | 'delete' | null>(null);
  const [inventoryActionItem, setInventoryActionItem] = useState<AccessoryItem | null>(null);

  // Search & Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Sales History Filters
  const [salesSearchTerm, setSalesSearchTerm] = useState('');
  const [salesDateFilter, setSalesDateFilter] = useState<'all' | 'today' | 'week' | 'month' | 'custom'>('all');
  const [salesCustomStart, setSalesCustomStart] = useState('');
  const [salesCustomEnd, setSalesCustomEnd] = useState('');

  // --- Handlers ---

  const handleOpenModal = (item?: AccessoryItem) => {
    setIsAddStockMode(false);
    if (item) {
      setEditingItem(item);
      setFormData({
        name: item.name,
        category: item.category,
        price: item.price.toString(),
        buyingPrice: item.buyingPrice.toString(),
        quantity: item.quantity.toString(),
        serialNumber: item.serialNumber || ''
      });
    } else {
      setEditingItem(null);
      setFormData({ 
        name: '', 
        category: categories.length > 0 ? categories[0].name : '', 
        price: '', 
        buyingPrice: '0', 
        quantity: '',
        serialNumber: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();

    if (isAddStockMode) {
       // Add Stock Logic
       const searchSN = formData.serialNumber.trim().toLowerCase();
       const existingItem = inventory.find(i => i.serialNumber.trim().toLowerCase() === searchSN);

       if (existingItem) {
          const qtyToAdd = Number(formData.quantity);

          if (isNaN(qtyToAdd) || qtyToAdd <= 0) {
             alert('Please enter a valid quantity greater than 0.');
             return;
          }

          setInventory(prev => prev.map(i => i.id === existingItem.id ? { ...i, quantity: i.quantity + qtyToAdd } : i));
          alert(`Added ${qtyToAdd} to ${existingItem.name}. New total: ${existingItem.quantity + qtyToAdd}`);
       } else {
          alert('Item with this Serial Number not found.');
          return;
       }
    } else {
       // Create/Update Logic
        // Check Serial Number Uniqueness
        if (formData.serialNumber.trim()) {
            const isDuplicate = inventory.some(i => 
                i.serialNumber.toLowerCase() === formData.serialNumber.trim().toLowerCase() && 
                i.id !== editingItem?.id
            );
            if (isDuplicate) {
                alert('Serial Number must be unique. This Serial Number already exists in the inventory.');
                return;
            }
        }

        if (editingItem) {
          setInventory(prev => prev.map(i => i.id === editingItem.id ? {
            ...i,
            name: formData.name,
            category: formData.category,
            price: Number(formData.price),
            buyingPrice: Number(formData.buyingPrice),
            quantity: Number(formData.quantity),
            serialNumber: formData.serialNumber
          } : i));
        } else {
          const newItem: AccessoryItem = {
            id: Date.now().toString(),
            name: formData.name,
            category: formData.category,
            price: Number(formData.price),
            buyingPrice: Number(formData.buyingPrice),
            quantity: Number(formData.quantity),
            serialNumber: formData.serialNumber
          };
          setInventory(prev => [...prev, newItem]);
        }
    }
    setIsModalOpen(false);
  };

  // One Click Save Handler
  const handleOneClickSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!oneClickCategory) {
        alert("Please select a category first.");
        return;
    }
    if (!oneClickData.name || !oneClickData.price || !oneClickData.quantity) {
        alert("Please fill in Name, Selling Price and Quantity.");
        return;
    }

    // Check Serial Duplication
    if (oneClickData.serialNumber.trim()) {
        const isDuplicate = inventory.some(i => i.serialNumber.toLowerCase() === oneClickData.serialNumber.trim().toLowerCase());
        if (isDuplicate) {
            alert("Serial Number already exists!");
            return;
        }
    }

    const newItem: AccessoryItem = {
        id: Date.now().toString(),
        name: oneClickData.name,
        category: oneClickCategory,
        price: Number(oneClickData.price),
        buyingPrice: Number(oneClickData.buyingPrice),
        quantity: Number(oneClickData.quantity),
        serialNumber: oneClickData.serialNumber
    };

    setInventory(prev => [newItem, ...prev]);

    // Reset Form but keep category
    setOneClickData({
        serialNumber: '',
        name: '',
        buyingPrice: '',
        price: '',
        quantity: ''
    });

    // Focus back to serial
    setTimeout(() => {
        oneClickSerialRef.current?.focus();
    }, 100);
  };

  // --- Bulk Mode Handlers ---
  const handleAddBulkRow = () => {
    setBulkItems(prev => [...prev, { serialNumber: '', name: '', buyingPrice: '', price: '', quantity: '' }]);
  };

  const handleRemoveBulkRow = (index: number) => {
    if (bulkItems.length > 1) {
      setBulkItems(prev => prev.filter((_, i) => i !== index));
    }
  };

  const handleBulkInputChange = (index: number, field: string, value: string) => {
    setBulkItems(prev => prev.map((item, i) => i === index ? { ...item, [field]: value } : item));
  };

  const handleBulkSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!oneClickCategory) {
        alert("Please select a category first.");
        return;
    }

    const validItems: AccessoryItem[] = [];
    const errors: string[] = [];
    const tempInventoryIds = new Set(inventory.map(i => i.serialNumber?.trim().toLowerCase()).filter(Boolean));
    const currentBatchSerials = new Set<string>();

    for (let i = 0; i < bulkItems.length; i++) {
        const item = bulkItems[i];
        // Ignore rows that are completely empty
        if (!item.name && !item.price && !item.quantity && !item.serialNumber && !item.buyingPrice) continue;

        if (!item.name || !item.price || !item.quantity) {
            errors.push(`Row ${i + 1}: Name, Price, and Quantity are required.`);
            continue;
        }

        if (item.serialNumber) {
            const sn = item.serialNumber.trim().toLowerCase();
            if (currentBatchSerials.has(sn)) {
                errors.push(`Row ${i + 1}: Duplicate Serial Number '${item.serialNumber}' in this batch.`);
                continue;
