            if (tempInventoryIds.has(sn)) {
                errors.push(`Row ${i + 1}: Serial Number '${item.serialNumber}' already exists in inventory.`);
                continue;
            }
            currentBatchSerials.add(sn);
        }

        validItems.push({
            id: Date.now().toString() + Math.random().toString(36).substring(2, 9) + i,
            name: item.name,
            category: oneClickCategory,
            price: Number(item.price),
            buyingPrice: Number(item.buyingPrice) || 0,
            quantity: Number(item.quantity),
            serialNumber: item.serialNumber
        });
    }

    if (errors.length > 0) {
        alert("Issues found:\n" + errors.join("\n"));
        return;
    }

    if (validItems.length === 0) {
        alert("Please fill in at least one item.");
        return;
    }

