       date: date,
       customerName: voucherCustomerName || 'Walk-in Customer',
       items: newSalesRecords,
       subtotal: subTotal,
       discountType: numDiscount > 0 ? discountType : undefined,
       discountValue: numDiscount > 0 ? numDiscount : undefined,
       totalAmount: finalTotal,
       status: 'Completed'
    };

